 9	namespace Application\Countries\API\Params;
10	
11	use Application\API\Parameters\APIParameterInterface;
12	use Application\API\Parameters\Validation\BaseParamValidation;
13	use Application\AppFactory;
14	use AppUtils\OperationResult;
15	
16	/**
17	 * Validates each country ISO code in a string list individually, producing
18	 * a per-ISO error message that identifies which ISO codes do not exist.
19	 *
20	 * This is necessary because {@see \Application\API\Parameters\Validation\Type\ValueExistsCallbackValidation}
21	 * passes the entire resolved value (the `string[]` array) to the callback as a
22	 * single argument — it does not iterate per item. Using a custom validation
23	 * class gives consumers precise feedback on which ISO codes are invalid.
24	 *
25	 * @package Countries
26	 * @subpackage API
27	 * @see AppCountryISOsParam
28	 */
29	class AppCountryISOsValidation extends BaseParamValidation
30	{
31	    public const int VALIDATION_COUNTRY_ISO_NOT_EXISTS = 184802;
32	
33	    public function validate(float|int|bool|array|string|null $value, OperationResult $result, APIParameterInterface $param): void
34	    {
35	        if(!is_array($value) || empty($value)) {
36	            return;
37	        }
38	
39	        $countries = AppFactory::createCountries();
40	        $invalid = array();
41	
42	        foreach($value as $iso) {
43	            if(!$countries->isoExists((string)$iso)) {
44	                $invalid[] = $iso;
45	            }
46	        }
47	
48	        if(!empty($invalid)) {
49	            $result->makeError(
50	                sprintf(
51	                    'The following country ISO codes do not exist for parameter `%s`: %s',
52	                    $param->getName(),
53	                    implode(', ', $invalid)
54	                ),
55	                self::VALIDATION_COUNTRY_ISO_NOT_EXISTS
56	            );
57	        }
58	    }
59	}

