 9	namespace Application\Countries\API\Params;
10	
11	use Application\API\Parameters\Type\StringListParameter;
12	use Application\AppFactory;
13	use Application_Countries_Country;
14	
15	/**
16	 * Country ISO codes parameter for the multi-country Countries API.
17	 *
18	 * Accepts one or more two-letter country ISO codes as a comma-separated
19	 * string or array. Each ISO code is validated individually via
20	 * {@see AppCountryISOsValidation}, which produces a per-ISO error message
21	 * identifying any ISO codes that do not exist.
22	 *
23	 * @package Countries
24	 * @subpackage API
25	 * @see AppCountryISOsHandler
26	 * @see AppCountriesParamInterface
27	 */
28	class AppCountryISOsParam extends StringListParameter implements AppCountriesParamInterface
29	{
30	    /**
31	     * The parameter name used in API requests.
32	     *
33	     * Mirrors the constant declared on {@see \Application\Countries\API\AppCountriesAPIInterface}
34	     * (available once WP-004 is implemented).
35	     */
36	    public const string PARAM_COUNTRY_ISOS = 'countryISOs';
37	
38	    public function __construct()
39	    {
40	        parent::__construct(self::PARAM_COUNTRY_ISOS, 'Country ISO codes');
41	
42	        $this
43	            ->setDescription('One or more two-letter country ISO codes (e.g. de, en, fr), as a comma-separated list or array. Case insensitive.')
44	            ->validateBy(new AppCountryISOsValidation());
45	    }
46	
47	    /**
48	     * Returns the resolved country objects for each ISO code in the parameter value.
49	     *
50	     * Returns an empty array if the parameter has no value.
51	     *
52	     * @return Application_Countries_Country[]
53	     */
54	    public function getCountries(): array
55	    {
56	        $isos = $this->getValue();
57	
58	        if($isos === null || empty($isos)) {
59	            return array();
60	        }
61	
62	        $result = array();
63	        $countries = AppFactory::createCountries();
64	
65	        foreach($isos as $iso) {
66	            $result[] = $countries->getByISO($iso);
67	        }
68	
69	        return $result;
70	    }
71	}

